#!/usr/bin/env node
/**
 * Renders evals/RESULTS.md (generated by `make results`; never hand-edited) into a static page,
 * public/media/results.html, for the demo video's last beat. A rendering only: every number is
 * copied verbatim from the markdown. Supports what RESULTS.md uses: headings, blockquotes,
 * paragraphs, bullet lists, pipe tables, **bold** and `code`.
 *
 * Usage: node scripts/render-results.mjs
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const frontend = path.resolve(here, "..");
const src = path.resolve(frontend, "..", "evals", "RESULTS.md");
const out = path.join(frontend, "public", "media", "results.html");

const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const inline = (s) =>
  esc(s)
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/`([^`]+)`/g, "<code>$1</code>");

const md = await readFile(src, "utf8");
const lines = md.split("\n");
const html = [];
for (let i = 0; i < lines.length; i++) {
  const l = lines[i];
  if (!l.trim()) continue;
  let m;
  if ((m = l.match(/^(#{1,6})\s+(.*)$/))) {
    html.push(`<h${m[1].length}>${inline(m[2])}</h${m[1].length}>`);
  } else if (l.startsWith(">")) {
    html.push(`<blockquote>${inline(l.replace(/^>\s?/, ""))}</blockquote>`);
  } else if (l.startsWith("|")) {
    const rows = [];
    while (i < lines.length && lines[i].startsWith("|")) rows.push(lines[i++]);
    i--;
    const cells = (r) => r.replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
    const head = cells(rows[0]);
    const body = rows.slice(2).map(cells);
    html.push(
      "<table><thead><tr>" +
        head.map((h) => `<th>${inline(h)}</th>`).join("") +
        "</tr></thead><tbody>" +
        body.map((r) => `<tr data-row="${esc(r[0])}">` + r.map((c) => `<td>${inline(c)}</td>`).join("") + "</tr>").join("") +
        "</tbody></table>",
    );
  } else if (/^\s*[-*]\s+/.test(l)) {
    const items = [];
    while (i < lines.length && /^\s*[-*]\s+/.test(lines[i])) items.push(lines[i++].replace(/^\s*[-*]\s+/, ""));
    i--;
    html.push("<ul>" + items.map((x) => `<li>${inline(x)}</li>`).join("") + "</ul>");
  } else {
    html.push(`<p>${inline(l)}</p>`);
  }
}

const page = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>Faultline: evals/RESULTS.md</title>
<style>
  body { background:#09090b; color:#e4e4e7; font: 15px/1.5 ui-sans-serif, system-ui, sans-serif; margin:0; }
  main { max-width: 1400px; margin: 0 auto; padding: 24px 32px 120px; }
  .src { color:#a1a1aa; font-size:13px; margin-bottom:8px; }
  h1 { font-size: 26px; margin: 0 0 8px; } h2 { font-size: 19px; margin: 22px 0 8px; color:#fafafa; }
  blockquote { margin:0 0 8px; color:#a1a1aa; } code { font-family: ui-monospace, monospace; color:#c4b5fd; }
  table { border-collapse: collapse; width: 100%; font-size: 14px; }
  th, td { border-bottom: 1px solid #27272a; padding: 6px 8px; text-align: left; vertical-align: top; }
  th { color:#a1a1aa; font-weight:500; }
  tr[data-row="A4"] td { background: rgba(239,68,68,.12); }
  tr[data-row="A3"] td { background: rgba(16,185,129,.10); }
  ul { margin: 4px 0; padding-left: 22px; } li { margin: 3px 0; }
</style></head>
<body><main>
<p class="src">Rendered verbatim from <code>evals/RESULTS.md</code> (generated by <code>evals/report.py</code>) by <code>frontend/scripts/render-results.mjs</code>.</p>
${html.join("\n")}
</main></body></html>
`;
await mkdir(path.dirname(out), { recursive: true });
await writeFile(out, page);
console.log(`wrote ${path.relative(frontend, out)} from ${path.relative(path.resolve(frontend, ".."), src)}`);
